import{_ as t,o as i,c as a,a3 as s}from"./chunks/framework.CRbjHCyB.js";const g=JSON.parse('{"title":"Lint","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Lint | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/clice/cli/lint"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/clice/cli/lint"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/clice/cli/lint"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/clice/cli/lint"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/clice/cli/lint"}]]},"headers":[],"relativePath":"clice/cli/lint.md","filePath":"en/clice/cli/lint.md","lastUpdated":1789832085000}'),l={name:"clice/cli/lint.md"};function c(n,e,o,r,d,h){return i(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="lint" tabindex="-1">Lint <a class="header-anchor" href="#lint" aria-label="Permalink to &quot;Lint&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>clice integrates clang-tidy as a built-in linting engine. <code>clice lint</code> runs the checks of your <code>.clang-tidy</code> over the workspace&#39;s translation units with a resident worker pool and prints one merged report.</p><p><strong>Usage</strong>: <code>clice lint [--workspace &lt;dir&gt;] [--configuration &lt;tag&gt;] [--workers &lt;n&gt;] [--index]</code></p><p>Runs clang-tidy over every translation unit of the compilation database that the lint set below admits, prints the merged findings, and exits non-zero when problems are found. <code>--index</code> additionally builds and persists the project index from the same parses, so a follow-up <code>clice index</code> run has nothing left to do.</p><p>Exit codes: <code>0</code> for a clean run, <code>1</code> when there are findings, <code>2</code> when the run could not complete as asked: a translation unit failed to run or the index could not be persisted. An interrupted run exits with <code>130</code>.</p><h2 id="what-is-checked" tabindex="-1">What is checked <a class="header-anchor" href="#what-is-checked" aria-label="Permalink to &quot;What is checked&quot;">​</a></h2><ul><li>Every translation unit the compilation database lists, inside the workspace.</li><li>Every header inside the workspace that the checked units include, subject to the <code>.clang-tidy</code> header filters (<code>HeaderFilterRegex</code>, <code>ExcludeHeaderFilterRegex</code>, <code>SystemHeaders</code>), read exactly as clang-tidy reads them.</li><li>Files outside the workspace are never checked, whether or not the build marks them as system headers. A rule in <code>clice.toml</code> with <code>lint = false</code> keeps matching files inside the workspace out as well, for example a vendored library:</li></ul><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rules</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">patterns = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;third_party/**&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">lint = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span></code></pre></div><p>Each translation unit takes its configuration from the nearest <code>.clang-tidy</code>, with the inheritance clang-tidy applies. <code>NOLINT</code>, <code>NOLINTNEXTLINE</code> and <code>NOLINTBEGIN</code>/<code>NOLINTEND</code> comments are honored in every file. A header is checked in every translation unit that includes it, as clang-tidy would; a finding several units report identically, notes included, appears once in the report, which is sorted by file and position and keeps the notes clang-tidy attaches.</p><h2 id="clang-tidy-integration-quality" tabindex="-1">clang-tidy Integration Quality <a class="header-anchor" href="#clang-tidy-integration-quality" aria-label="Permalink to &quot;clang-tidy Integration Quality&quot;">​</a></h2><p>Issues that affect the quality of clang-tidy diagnostics within a language server:</p><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> Suppress clang-tidy warnings from macros in system headers (<a href="https://github.com/clangd/clangd/issues/1587" target="_blank" rel="noreferrer">clangd#1587</a>, <a href="https://github.com/clangd/clangd/issues/2000" target="_blank" rel="noreferrer">clangd#2000</a>)</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> Run checks on preprocessor directives in preamble (header guards, macros) (<a href="https://github.com/clangd/clangd/issues/2501" target="_blank" rel="noreferrer">clangd#2501</a>, <a href="https://github.com/clangd/clangd/issues/160" target="_blank" rel="noreferrer">clangd#160</a>)</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> Configurable diagnostic severity per check category (<a href="https://github.com/clangd/clangd/issues/1937" target="_blank" rel="noreferrer">clangd#1937</a>)</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> Support loading clang-tidy plugins (<a href="https://github.com/clangd/clangd/issues/1458" target="_blank" rel="noreferrer">clangd#1458</a>)</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> Clang static analyzer support (<a href="https://github.com/clangd/clangd/issues/905" target="_blank" rel="noreferrer">clangd#905</a>)</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> Clean up replacements when applying clang-tidy fixes (<a href="https://github.com/clangd/clangd/issues/429" target="_blank" rel="noreferrer">clangd#429</a>)</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> Filter diagnostics by version control diff (<a href="https://github.com/clangd/clangd/issues/822" target="_blank" rel="noreferrer">clangd#822</a>)</li><li class="task-list-item"><input class="task-list-item-checkbox" checked="" disabled="" type="checkbox"> NOLINT / NOLINTNEXTLINE / NOLINTBEGIN-END comment suppression</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> <code>Diagnostics.ClangTidy</code> configuration in <code>.clangd</code> config</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> Fast-check filtering for clang-tidy performance</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> Fix-it suggestions from clang-tidy as code actions</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> Diagnostic metadata: check name, documentation URL, source tag</li></ul>`,13)])])}const k=t(l,[["render",c]]);export{g as __pageData,k as default};
